import { describe, expect, test } from "bun:test";
import { blindPair, parseVerdict } from "../src/grade/judge.ts";
import type { JudgeInput } from "../src/grade/judge.ts";

const a: JudgeInput = { setup: "setup-alpha", diff: "diff from alpha\nline2" };
const b: JudgeInput = { setup: "setup-beta", diff: "diff from beta\nline2" };
const labels = { X: a.setup, Y: b.setup };

/** The section of the prompt under one label, up to the next label. */
function section(prompt: string, label: "X" | "Y"): string {
  const from = prompt.indexOf(`=== Change ${label} ===`);
  const to = prompt.indexOf("=== Change", from + 1);
  return prompt.slice(from, to === -1 ? undefined : to);
}

describe("blindPair", () => {
  test("prompt carries both diffs under the X and Y labels", () => {
    const { prompt } = blindPair(a, b, 123);
    expect(prompt).toContain(a.diff);
    expect(prompt).toContain(b.diff);
    expect(section(prompt, "X")).toContain("=== Change X ===");
    expect(section(prompt, "Y")).toContain("=== Change Y ===");
  });

  test("lays the diffs out under the labels it reports", () => {
    const { prompt, labels: l } = blindPair(a, b, 123);
    const underX = l.X === a.setup ? a.diff : b.diff;
    const underY = l.Y === a.setup ? a.diff : b.diff;
    expect(section(prompt, "X")).toContain(underX);
    expect(section(prompt, "Y")).toContain(underY);
  });

  test("never contains either setup id", () => {
    for (const seed of [1, 2, 3, 42, 123, 999]) {
      const { prompt } = blindPair(a, b, seed);
      expect(prompt).not.toContain(a.setup);
      expect(prompt).not.toContain(b.setup);
    }
  });

  test("scrubs a setup id that leaks inside a diff", () => {
    const leaky = { setup: "setup-alpha", diff: "commit by setup-alpha on forward/F27/old" };
    const { prompt } = blindPair(leaky, b, 7);
    expect(prompt).not.toContain("setup-alpha");
    expect(prompt).not.toContain("forward/F27/old");
    expect(prompt).toContain("<setup>");
    expect(prompt).toContain("<branch>");
  });

  test("labels map X and Y onto the two setup ids", () => {
    const { labels: l } = blindPair(a, b, 123);
    expect([l.X, l.Y].sort()).toEqual([a.setup, b.setup].sort());
  });

  test("the same seed reproduces the assignment and the prompt", () => {
    expect(blindPair(a, b, 42)).toEqual(blindPair(a, b, 42));
  });

  test("the coin flip actually flips across seeds", () => {
    const orders = new Set([1, 2, 3, 4, 5, 6, 7, 8].map((s) => blindPair(a, b, s).labels.X));
    expect(orders).toEqual(new Set([a.setup, b.setup]));
  });
});

describe("parseVerdict", () => {
  test("maps each label back to its setup id", () => {
    expect(parseVerdict("VERDICT: X", labels)).toEqual({ winner: a.setup });
    expect(parseVerdict("VERDICT: Y", labels)).toEqual({ winner: b.setup });
    expect(parseVerdict("VERDICT: TIE", labels)).toEqual({ winner: "tie" });
  });

  test("is case-insensitive", () => {
    expect(parseVerdict("verdict: x", labels)).toEqual({ winner: a.setup });
    expect(parseVerdict("Verdict: y", labels)).toEqual({ winner: b.setup });
    expect(parseVerdict("VERDICT: tie", labels)).toEqual({ winner: "tie" });
  });

  test("the last occurrence wins", () => {
    expect(parseVerdict("VERDICT: X\nVERDICT: Y", labels)).toEqual({ winner: b.setup });
    expect(parseVerdict("VERDICT: Y\nVERDICT: TIE", labels)).toEqual({ winner: "tie" });
    expect(parseVerdict("VERDICT: TIE\nVERDICT: x", labels)).toEqual({ winner: a.setup });
    expect(parseVerdict("VERDICT: X\nreasoning\nVERDICT: Z", labels)).toEqual({ winner: "unclear" });
  });

  test("reads the verdict line out of surrounding prose", () => {
    expect(parseVerdict("X is much cleaner.\nVERDICT: X", labels)).toEqual({ winner: a.setup });
    expect(parseVerdict("**VERDICT: Y**", labels)).toEqual({ winner: b.setup });
    expect(parseVerdict("VERDICT: X.", labels)).toEqual({ winner: a.setup });
  });

  test("anything else is unclear", () => {
    expect(parseVerdict("no verdict here", labels)).toEqual({ winner: "unclear" });
    expect(parseVerdict("", labels)).toEqual({ winner: "unclear" });
    expect(parseVerdict(null, labels)).toEqual({ winner: "unclear" });
    expect(parseVerdict("VERDICT: Z", labels)).toEqual({ winner: "unclear" });
    expect(parseVerdict("VERDICT: Xylophone", labels)).toEqual({ winner: "unclear" });
    expect(parseVerdict("The winner is X", labels)).toEqual({ winner: "unclear" });
  });

  test("round-trips through blindPair for both orders", () => {
    for (const seed of [42, 123]) {
      const { labels: l } = blindPair(a, b, seed);
      for (const [label, setup] of [["X", l.X], ["Y", l.Y]] as const) {
        expect(parseVerdict(`VERDICT: ${label}`, l)).toEqual({ winner: setup });
      }
    }
  });
});

